                    text: "The Valdai 18 FB6R31 fuel tanker from RusTrak is designed for the safe transportation, storage, and dispensing of light petroleum products. The two-section tank with a capacity of 10,000 liters allows fuel to be separated by type, while the Valdai 18 chassis with a 4x2 wheel formula combines reliability, durability, and economical operation.",
